FR = (16, 48, 96, 64, 128, 384, 256, 512, 512, 0)
BK = (0, 0, 0, 0, 3, 6, 12, 48, 96, 384)
NB = (18, 53, 106, 68, 163, 470, 300, 816, 736, 384)
RM = (15, 112, 384, 512)
RG = range(10)
GRP = {}


def fl(S):
    """out of turn: fell although every pin in front of it still stands"""
    return sum(1 << c for c in RG if S >> c & 1 and FR[c] and not S & FR[c])


def ex(S):
    return sum(1 << c for c in RG if S >> c & 1 and FR[c] and S & FR[c] != FR[c])


def mi(S):
    return sum(1 << c for c in RG if S >> c & 1 and BK[c] and not S & BK[c])


def bc(x):
    return x.bit_count()


def grp(d):
    if d not in GRP:
        g = {}
        for c in itertools.combinations(RG, d):
            S = sum(1 << k for k in c)
            g.setdefault(fl(S), []).append(S)
        GRP[d] = g
    return GRP[d]


def quality(F, n, grade):
    m = len(F)
    G = [fl(S) for S in F]
    E = [ex(S) for S in F]
    M = [mi(S) for S in F]
    per = [bc(G[k] & G[k + 1]) for k in range(m - 1)]
    dn = sum(map(bc, F))
    hard = (sum(map(bc, G)),
            sum(bc(G[k] & F[k + 1]) for k in range(m - 1)),
            sum(bc(E[k] & E[k + 1]) for k in range(m - 1)),
            sum(bc(M[k] & M[k + 1]) for k in range(m - 1)),
            sum(bc(G[k] & ((G[k - 1] if k else 0) | (G[k + 1] if k + 1 < m else 0)))
                for k in range(m)),
            sum(1 for k in range(m - 1) if G[k] and G[k + 1]))
    soft = (sum(bc(G[k] & G[k + 2]) for k in range(m - 2)),
            sum(bc(G[k] & F[k - 1]) for k in range(1, m)),
            sum(bc(G[k] & ~F[k + 1]) for k in range(m - 1)),
            sum(sum(1 for c in RG if S >> c & 1 and not S & NB[c]) for S in F),
            sum(sum(1 for c in RG if not S >> c & 1 and FR[c] and S & FR[c] == FR[c]) for S in F),
            sum(bc(S & 15) for S in F), sum(sum(S & x == x for x in RM) for S in F),
            sum(S >> 9 & 1 for S in F), sum(1 for v in per if v), sum(1 for v in per if not v),
            m - 1, dn, 10 * m - dn, sum(map(bc, E)), sum(map(bc, M)))
    if n and (n in (hard, hard[:2])[grade > 1]
              or (grade < 2 and (sum(v == n for v in soft) > 2 or not all(hard)))):
        return False
    two = gm = gs = fm = deep = 0
    for k in range(m - 1):
        for i, j in ((k, k + 1), (k + 1, k)):
            A, S = G[i], F[i]
            for c in RG:
                if not FR[c]:
                    continue
                if A >> c & 1:
                    if G[j] >> c & 1:
                        two += bc(FR[c]) == 2
                    elif F[j] >> c & 1:
                        gm += 1
                    else:
                        gs += 1
                elif S >> c & 1 and G[j] >> c & 1:
                    st = FR[c] & ~S
                    fm += st > 0
                    deep += st == 0
    h = sum(S >> 9 & 1 for S in F)
    if grade > 1:
        return True
    ok = gm and gs and fm and deep and 0 < h < m
    if grade:
        return bool(ok and (two or not n))
    return bool(ok and (not n or (two and any(per) and (n < 2 or not min(per))
                                  and (n < 3 or max(per) > 1))))


def draw(dig, F):
    out = ["|".join(str(x).center(7) for x in dig)]
    for r in range(4):
        o = (0, 4, 7, 9)[r]
        out.append("|".join((" " * r + " ".join("." if S >> (o + i) & 1 else "o"
                                                for i in range(4 - r))).ljust(7) for S in F))
    return "\n".join(x.rstrip() for x in out)


def solve(clue):
    a, b = clue.split("/")
    dig = [int(x) for x in a.split("|")]
    n = int(b)
    m = len(dig)
    r = random.Random(clue)
    D = [grp(x) for x in dig]
    KS = [sorted(g) for g in D]
    ach = [{f: 1 for f in KS[m - 1]}] * m
    for k in range(m - 2, -1, -1):
        it = list(ach[k + 1].items())
        cur = {}
        for f in KS[k]:
            v = 0
            for f2, a2 in it:
                v |= a2 << bc(f & f2)
            cur[f] = v
        ach[k] = cur

    def build():
        rem = n
        cand = [f for f in KS[0] if ach[0][f] >> rem & 1]
        if not cand:
            return None
        fm = [r.choice(cand)]
        for k in range(m - 1):
            P = KS[k + 1]
            L = len(P)
            st, got = r.randrange(L), None
            for j in range(L):
                f2 = P[(st + j) % L]
                v = bc(fm[k] & f2)
                if v <= rem and ach[k + 1][f2] >> (rem - v) & 1:
                    got, rem = f2, rem - v
                    break
            if got is None:
                return None
            fm.append(got)
        return [r.choice(D[k][f]) for k, f in enumerate(fm)]

    best = None
    for grade in (0, 1, 2):
        for _ in range(200 if grade < 2 else 120):
            F = build()
            if F is None:
                return draw(dig, best) if best else ""
            if quality(F, n, grade):
                return draw(dig, F)
            best = F
    return draw(dig, best) if best else ""

